(function () { var container = document.getElementById('hero-particles'); if (!container) return; var PARTICLE_COUNT = 20; function createParticle() { var particle = document.createElement('div'); particle.className = 'gold-particle'; particle.style.left = Math.random() * 100 + '%'; particle.style.top = Math.random() * 100 + '%'; particle.style.width = (2 + Math.random() * 4) + 'px'; particle.style.height = particle.style.width; particle.style.opacity = 0; container.appendChild(particle); return particle; } function animateParticle(particle) { var delay = Math.random() * 3000; var duration = 2000 + Math.random() * 2000; setTimeout(function () { particle.classList.add('animate'); particle.style.animationDuration = duration + 'ms'; setTimeout(function () { particle.classList.remove('animate'); particle.style.opacity = '0'; animateParticle(particle); }, duration); }, delay); } for (var i = 0; i < PARTICLE_COUNT; i++) { animateParticle(createParticle()); } })();